library(shiny)
library(shinylive)
library(shinydashboard)
library(httr)
library(jsonlite)

#suspectlist <- readRDS('www/suspect_list.RDS')
# url <- "https://data.nist.gov/od/ds/ark:/88434/mds2-2387/PFAS%20Suspect%20List.xlsx"
# download.file(url, "suspectlist.xlsx")
# suspectlist <- openxlsx::read.xlsx(xlsxFile = "suspectlist.xlsx", sheet = 1)
suspectlist <- reactiveValues(slist = NULL)
file_url <- "https://raw.githubusercontent.com/usnistgov/NISTPFAS/refs/heads/shinylive/suspectlist/lib/suspectlist.JSON"
suspectlist$slist <- jsonlite::fromJSON(file_url)

extract_elements <- function(composition.str, remove.elements = c()) {
  single.elem <- gregexpr("[A-Z]", composition.str)[[1]]
  double.elem <- gregexpr("[A-Z][a-z]", composition.str)[[1]]
  single.elem <- single.elem[! single.elem %in% double.elem]
  if (length(single.elem) > 0) {
    elements <- substring(composition.str, single.elem, single.elem)
  }
  if (double.elem[1] != -1) {
    elements <- c(elements, substring(composition.str, double.elem, double.elem + 1))
  }
  ecounts <- rep(1, length(elements))
  nums <- gregexpr("[0-9]+", composition.str)[[1]]
  nums.count <- attr(nums, "match.length")
  for (i in 1:length(nums)) {
    if (substr(composition.str, nums[i] - 1, nums[i] - 1) %in% elements) {
      ecounts[which(elements == substr(composition.str, nums[i] - 1, nums[i] - 1))] <- substr(composition.str, nums[i], nums[i] + nums.count[i] - 1)
    }
    if (substr(composition.str, nums[i] - 2, nums[i] - 1) %in% elements) {
      ecounts[which(elements == substr(composition.str, nums[i] - 2, nums[i] - 1))] <- substr(composition.str, nums[i], nums[i] + nums.count[i] - 1)
    }
  }
  results <- c()
  results$elements <- elements
  results$counts <- as.integer(ecounts)
  results$counts <- results$counts[which(!results$elements %in% remove.elements)]
  results$elements <- results$elements[which(!results$elements %in% remove.elements)]
  results
}

formulalize <- function(formula) {
  extract_formula <- extract_elements(formula) #from qualitycontrol functions
  if ("C" %in% extract_formula$elements) {
    c_wo_c <- extract_formula$counts[-which(extract_formula$elements == "C")]
    e_wo_c <- extract_formula$elements[-which(extract_formula$elements == "C")]
    elements <- c("C", e_wo_c[order(e_wo_c)])
    counts <- c(extract_formula$counts[which(extract_formula$elements == "C")], c_wo_c[order(e_wo_c)])
  }
  if (!"C" %in% extract_formula$elements) {
    elements <- extract_formula$elements[order(extract_formula$elements)]
    counts <- extract_formula$counts[order(extract_formula$elements)]
  }
  paste(elements, counts, sep = "", collapse = "")
}

ui <- dashboardPage(
  dashboardHeader(title = "Suspect List Viewer"),
  dashboardSidebar(
    sidebarMenu(
    menuItem("About", tabName = "abouttab", icon = icon("question")),
    menuItem("Suspect List", tabName = "listtab", icon = icon("newspaper")),
    menuItem("Search List", tabName = "searchtab", icon = icon("magnifying-glass")),
    menuItem("Export List", tabName = "exporttab", icon = icon("download")),
    actionButton("browser", "Use Browser")
    )
  ),
  dashboardBody(
    tabItems(
      tabItem(tabName = "abouttab",
              h3("About the NIST Suspect List"),
              p("Text will go here"),
              fileInput("suspectlistfile",
                        "Choose CSV File",
                        multiple = FALSE,
                        accept = c(
                          "text/csv",
                          "text/comma-separated-values,text/plain",
                          ".csv"
                        )
              )
              ),
      tabItem(tabName = "listtab",
              h3("Suspect List"),
              DT::dataTableOutput("suspectlist")
              ),
      tabItem(tabName = "searchtab",
              h3("Search Suspect List"),
              
              fluidRow(box(title = "Search by mass", width = 4, collapsible = TRUE,
              numericInput("searchmass", "Mass value", value = "498.9302", min = 0, max = NA, step = 0.0001, width = '50%'),
              numericInput("masserror", "Mass Error (in ppm)", value = 5, min = 0, max = NA, step = 0.1, width = '50%'),
              checkboxGroupInput("adducts", "Select adducts to include:",
                                 choices = c("neutral", "M-H", "M-H2O+H", "M+H", "M+K", "M+Na" )),
              actionButton("searchmassbutton", "Search by mass")
              ),
              box(title = "Search by formula", width = 4, collapsible = TRUE,
                  textInput("searchformula", "Enter Elemental Formula", value = "C8F17SO3H", width = '50%'),
                  actionButton("searchformulabutton", "Search by formula")
                  )
              ),
              fluidRow(
                DT::dataTableOutput("searchresult")
              )
              ),
      tabItem(tabName = "exporttab",
              box(title = "Export PFAS Suspect List",
                  checkboxGroupInput("exportvalues", "Select values to export", choices = NULL, inline = TRUE),
                  actionButton("selectall", "Select All values"),
                  downloadButton("exportlist"))
              )
    )
  )
)


server <- function(input, output, session) {
  

  # suspectlist$slist <- jsonlite::fromJSON(httr::content(httr::GET(file_url, as = "text")))
  #download.file(file_url, "suspectlist.JSON")
  #suspectlist$slist <- jsonlite::fromJSON("suspectlist.JSON")
  
  
  observeEvent(suspectlist$slist, updateCheckboxGroupInput(session, "exportvalues", choices = colnames(suspectlist$slist)))
  
  observeEvent(input$browser, browser())
  
   output$suspectlist <- DT::renderDataTable({
     
     req(suspectlist$slist, cancelOutput = FALSE)
     suspectlist$slist
     
   },rownames = FALSE, options = list(scrollX = TRUE))
  
  observeEvent(input$searchmassbutton, isolate({
    H_plus = 1.0072767
    Na_plus = 22.9892213
    K_plus = 38.9631585
    H2O = 18.01056
    
    adducts <- input$adducts
    if (is.null(adducts)) {adducts <- "neutral"}
    
    mass <- input$searchmass
    masserror <- input$masserror
    minmass <- mass - (masserror*mass*1E-6)
    maxmass <- mass + (masserror*mass*1E-6)
    
    masses <- suspectlist$slist$FIXEDMASS
    netcharge <- suspectlist$slist$NETCHARGE
    
    ind <- NA
    
    
    if ("neutral" %in% adducts) {
    ind <- c(ind, which(masses >= minmass & masses <= maxmass))
    }
    if ("M-H" %in% adducts) {
      ind <- c(ind, which((masses - (netcharge + 1)*H_plus) >= minmass & (masses - (netcharge + 1)*H_plus) <= maxmass))
    }
    if ("M+H" %in% adducts) {
      ind <- c(ind, which((masses + (-netcharge + 1)*H_plus) >= minmass & (masses + (-netcharge + 1)*H_plus) <= maxmass))
    }
    if ("M+Na" %in% adducts) {
      ind <- c(ind, which((masses + (-netcharge + 1)*Na_plus) >= minmass & (masses + (-netcharge + 1)*Na_plus) <= maxmass))
    }
    if ("M+K" %in% adducts) {
      ind <- c(ind, which((masses + (-netcharge + 1)*K_plus) >= minmass & (masses + (-netcharge + 1)*K_plus) <= maxmass))
    }
    if ("M-H2O+H" %in% adducts) {
      ind <- c(ind, which((masses - H2O + (-netcharge + 1)*H_plus) >= minmass & (masses - H2O + (-netcharge + 1)*H_plus) <= maxmass))
    }
    ind <- sort(unique(ind))
    output$searchresult <- DT::renderDataTable(suspectlist$slist[ind,])
  }))
  
  observeEvent(input$searchformulabutton, isolate({
    searchformula <- input$searchformula
    searchformula <- formulalize(searchformula)
    formulas <- sapply(suspectlist$slist$FORMULA, formulalize)
    ind <- which(formulas == searchformula)
    
    output$searchresult <- DT::renderDataTable(suspectlist$slist[ind,])
    
  }))
  
  observeEvent(input$selectall, isolate({
    if (length(which(input$exportvalues %in% colnames(suspectlist$slist))) == length(colnames(suspectlist$slist))) {
      updateCheckboxGroupInput(session, "exportvalues", selected = c("SUSPECTID", "CHEMICAL_NAME", "INCHI"))
    }
    if (length(which(input$exportvalues %in% colnames(suspectlist$slist))) != length(colnames(suspectlist$slist))) {
      updateCheckboxGroupInput(session, "exportvalues", selected = colnames(suspectlist$slist))
    }
  }))
  
  output$exportlist <- downloadHandler(
    filename = function() {
      paste("NIST PFAS suspect List", Sys.Date(), ".csv", sep = "")
    },
    content = function(file) {
      values <- input$exportvalues
      dat <- suspectlist$slist[,values]
      write.csv(dat, file, row.names = FALSE)
    }
  )
}

# Run the application 
shinyApp(ui = ui, server = server)
